use std::{fs,path::Path,collections::HashSet,ffi::OsString,os::windows::ffi::OsStringExt,time::Instant}; use tg_package_integrity as pi;
fn gated(json:&[u8])->Vec<u8>{let mut b=json.to_vec();for n in 0..1_000_000u32{b.truncate(json.len());for bit in 0..20{b.push(if n&(1<<bit)==0{b' '}else{b'\t'});}if pi::is_valid_manifest_checksum(&b){return b}}panic!("no gate")}
fn main(){let root=std::env::args().nth(1).unwrap();let base=Path::new(&root);fs::create_dir_all(base).unwrap();for (label,json) in [("u32_overflow",r#"{"version":4294967296,"files":[]}"#),("negative_version",r#"{"version":-1,"files":[]}"#),("float_version",r#"{"version":1.0,"files":[]}"#),("duplicate_version",r#"{"version":1,"version":1,"files":[]}"#),("missing_files",r#"{"version":1}"#),("unknown_field",r#"{"version":1,"files":[],"future":true}"#),("sequence_form",r#"[1,[]]"#),("files_bad_tuple",r#"{"version":1,"files":[["a"]]}"#)]{let bytes=gated(json.as_bytes());println!("schema {label}: {:?}",pi::verify_manifest_bytes(base.join("empty"),&bytes));}
fs::create_dir_all(base.join("extra/sub/tmp")).unwrap();fs::create_dir_all(base.join("extra/tmp")).unwrap();fs::write(base.join("extra/正常🌱.txt"),b"x").unwrap();fs::write(base.join("extra/sub/tmp/nested"),b"x").unwrap();fs::write(base.join("extra/tmp/ignored"),b"x").unwrap();let bad=base.join("extra").join(OsString::from_wide(&[0xd800]));println!("bad_unicode create {:?}",fs::write(&bad,b"x"));println!("extra {:?}",pi::find_extra_files(base.join("extra"),&HashSet::new()));
let d=base.join("checks");fs::create_dir_all(d.join("dir" )).unwrap();fs::write(d.join("a"),b"x").unwrap();let h=blake3::hash(b"x").to_hex().to_string();let mut entries=Vec::new();for i in 0..130 {entries.push(format!(r#"["missing-{i:03}","x"]"#));}entries.extend([format!(r#"["a","{h}"]"#),format!(r#"["a","{}"]"#,h.to_uppercase()),r#"["dir","x"]"#.into(),r#"["build-info/manifest.json","ignored"]"#.into()]);let j=format!(r#"{{"version":1,"files":[{}]}}"#,entries.join(","));let bytes=gated(j.as_bytes());let now=Instant::now();println!("aggregate {:?}",pi::verify_manifest_bytes(&d,&bytes));println!("aggregate elapsed_ms {}",now.elapsed().as_millis());
}